{
  "requirement_id": "REQ-007",
  "cases": [
    {
      "id": "TC-1",
      "title": "Project member can read task detail",
      "surface": "api",
      "steps": [
        "Alice creates project P1",
        "Alice creates task T1 in P1",
        "Alice requests GET /api/tasks/T1 with header X-User: alice"
      ],
      "expected": "專案、任務列表與任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取"
    },
    {
      "id": "TC-2",
      "title": "Non-project member is forbidden from reading task detail",
      "surface": "api",
      "steps": [
        "Alice creates project P1",
        "Alice creates task T1 in P1",
        "Bob requests GET /api/tasks/T1 with header X-User: bob"
      ],
      "expected": "非專案成員訪問回傳 403 錯誤"
    },
    {
      "id": "TC-3",
      "title": "Reading non-existent task returns 404",
      "surface": "api",
      "steps": [
        "Alice requests GET /api/tasks/non-existent-tid with header X-User: alice"
      ],
      "expected": "資源不存在時回傳 404 錯誤"
    }
  ]
}

